package com.ute.uteexpress.operations;

import com.ute.uteexpress.dto.admin.*;
import com.ute.uteexpress.dto.admin.ReportViews.*;
import com.ute.uteexpress.dto.admin.ReportViews.Period;
import com.ute.uteexpress.dto.operations.TicketCommands;
import com.ute.uteexpress.dto.operations.CustomerTicketCommands;
import com.ute.uteexpress.entity.*;
import com.ute.uteexpress.enums.*;
import com.ute.uteexpress.service.reports.*;
import com.ute.uteexpress.service.AdminUserService;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.test.context.junit.jupiter.SpringJUnitConfig;
import static com.ute.uteexpress.operations.OperationsJdbcFixture.*;
import static org.junit.jupiter.api.Assertions.*;

@SpringJUnitConfig(AdminReportingJdbcConfig.class)
class AdminOperationalReportTests extends OperationsJdbcSupport {
    @Autowired AdminReportService reports;@Autowired AdminAuditService audit;@Autowired AdminUserService adminUsers;
    Request req(Dataset d){return new Request(d,Period.TODAY,null,null,null,null,null,Trend.DAY);}
    Dashboard report(Dataset d){as(f.admin,"ROLE_ADMIN");return reports.read(req(d),0,50);}
    Employee staff(Branch b){return em.createQuery("select e from Employee e where e.branch.id=:branch",Employee.class).setParameter("branch",b.getId()).setMaxResults(1).getResultStream().findFirst().orElseGet(()->{var u=f.user("staff-"+b.getCode(),"ROLE_MANAGER");var e=f.employee(u,b,EmployeePosition.WAREHOUSE_STAFF);f.membership(u,b);return e;});}
    TransportTrip trip(Branch from,Branch to,TransportLeg leg,TripStatus status){
        var route=new TransportRoute();route.setOrigin(from);route.setDestination(to);route.setLeg(leg);em.persist(route);
        var sender=staff(from);var receiver=staff(to);var t=new TransportTrip();t.setRoute(route);t.setOrigin(from);t.setDestination(to);t.setLeg(leg);t.setStatus(status);t.setCode("TR"+UUID.randomUUID().toString().substring(0,20));t.setRequestToken(UUID.randomUUID().toString().replace("-",""));t.setCreatedBy(sender.getUser());t.setCreatedAt(NOW.minusHours(4));t.setExpectedCount(1);
        t.setSealedBy(sender.getUser());t.setSealedAt(NOW.minusHours(3));t.setDepartedBy(sender.getUser());t.setDepartedEmployee(sender);t.setDepartedAt(NOW.minusHours(2));if(status==TripStatus.RECONCILING||status==TripStatus.CLOSED){t.setArrivedBy(receiver.getUser());t.setArrivedAt(NOW.minusHours(1));}if(status==TripStatus.CLOSED){t.setClosedBy(receiver.getUser());t.setClosedAt(NOW);}em.persist(t);return t;
    }
    TransportTripItem item(TransportTrip trip,Shipment s,boolean received){var i=new TransportTripItem();i.setTrip(trip);i.setShipment(s);i.setAddedAt(NOW.minusHours(3));if(received){i.setStatus(TripItemStatus.RECEIVED);i.setActive(false);}em.persist(i);if(received){var receiver=staff(trip.getDestination());var r=new TripReceipt();r.setItem(i);r.setBranch(trip.getDestination());r.setActor(receiver.getUser());r.setEmployee(receiver);r.setReference("PRIVATE RECEIPT REF");r.setNotes("PRIVATE RECEIPT NOTES");r.setReceivedAt(NOW);em.persist(r);}return i;}
    @Test void multipleTransportLegsAreTwoMovementsButOneUniqueShipment(){db(()->{var s=f.shipment(f.source,f.destination,ShipmentStatus.AT_DESTINATION_BRANCH,NOW);item(trip(f.source,f.hub,TransportLeg.COLLECTION,TripStatus.CLOSED),s,true);item(trip(f.hub,f.destination,TransportLeg.DISTRIBUTION,TripStatus.CLOSED),s,true);return null;});var view=report(Dataset.TRIPS);assertEquals(2,view.details().total());assertTrue(view.metrics().stream().anyMatch(m->m.label().equals("Lượt vận chuyển kiện/chặng")&&m.value().equals("2")));assertTrue(view.metrics().stream().anyMatch(m->m.label().equals("Vận đơn duy nhất qua các chặng")&&m.value().equals("1")));assertEquals(2,report(Dataset.TRIP_RECEIPTS).details().total());assertTrue(report(Dataset.TRIP_RECEIPTS).metrics().stream().anyMatch(m->m.label().equals("Vận đơn duy nhất trong tập đang lọc")&&m.value().equals("1")));assertFalse(view.toString().contains("PRIVATE"));}
    @Test void departedTripIsNotReceiptAndArrivalStillRequiresParcelReceipt(){db(()->{var s=f.shipment(f.source,f.destination,ShipmentStatus.IN_TRANSIT,NOW);item(trip(f.source,f.hub,TransportLeg.COLLECTION,TripStatus.DEPARTED),s,false);return null;});assertEquals(0,report(Dataset.TRIP_RECEIPTS).details().total());db(()->{var t=em.createQuery("select t from TransportTrip t",TransportTrip.class).getSingleResult();t.setStatus(TripStatus.RECONCILING);t.setArrivedBy(staff(f.hub).getUser());t.setArrivedAt(NOW);return null;});assertEquals(0,report(Dataset.TRIP_RECEIPTS).details().total());assertTrue(report(Dataset.TRIPS).metrics().stream().anyMatch(m->m.label().startsWith("Chuyến CLOSED")&&m.value().equals("0")));}
    @Test void openDiscrepancySnapshotIncludesOldRecordsAndNeverPublishesNotes(){db(()->{var t=trip(f.source,f.hub,TransportLeg.COLLECTION,TripStatus.RECONCILING);var d=new TripDiscrepancy();d.setTrip(t);d.setKind(TripDiscrepancyKind.UNEXPECTED);d.setReference("PRIVATE REF");d.setNotes("INTERNAL DISCREPANCY NOTES");d.setActor(staff(f.hub).getUser());d.setEmployee(staff(f.hub));d.setRecordedAt(NOW.minusDays(20));em.persist(d);return null;});assertEquals(0,report(Dataset.DISCREPANCIES).details().total());var snapshot=report(Dataset.OPEN_DISCREPANCIES);assertEquals(1,snapshot.details().total());assertFalse(snapshot.toString().contains("INTERNAL DISCREPANCY"));assertTrue(report(Dataset.TRIPS).metrics().stream().anyMatch(m->m.label().equals("Chuyến có sai lệch")&&m.value().equals("1")));}
    @Test void returnInitiationEventsAreDistinctFromRequestsAndActualReceipts(){db(()->{var s=f.shipment(f.source,f.destination,ShipmentStatus.RETURNING,NOW);f.event(s,"Manager khởi tạo hoàn",ShipmentStatus.DELIVERY_FAILED,ShipmentStatus.RETURNING,NOW);f.event(s,"Đang vận chuyển hoàn",ShipmentStatus.RETURNING,ShipmentStatus.RETURNING,NOW);return null;});assertEquals(1,report(Dataset.RETURN_STARTED).details().total());assertEquals(0,report(Dataset.RETURN_REQUESTS).details().total());assertEquals(0,report(Dataset.RETURNED).details().total());}
    Long resolvedOldTicket(){
        var s=db(()->f.shipment(f.source,f.destination,ShipmentStatus.DELIVERED,NOW.minusDays(12)));clock.set(NOW.minusDays(10));as(f.manager,"ROLE_MANAGER");Long id=tickets.create(command(s));clock.set(NOW);tickets.assign(id,new TicketCommands.Assign(ticketRows.findById(id).orElseThrow().getVersion(),f.secondEmployee.getId(),null));tickets.changeStatus(id,new TicketCommands.ChangeStatus(ticketRows.findById(id).orElseThrow().getVersion(),TicketStatus.PROCESSING,null));tickets.resolve(id,new TicketCommands.Decision(ticketRows.findById(id).orElseThrow().getVersion(),"PRIVATE PUBLIC RESOLUTION BODY"));return id;
    }
    @Test void customerReopenRequestIsNotActualReopenedAndResolutionIsInPeriodForOldTicket(){Long id=resolvedOldTicket();as(f.owner,"ROLE_USER");tickets.requestCustomerReopen(id,new CustomerTicketCommands.Message(ticketRows.findById(id).orElseThrow().getVersion(),"PRIVATE CUSTOMER REQUEST",UUID.randomUUID().toString().replace("-","")));assertEquals(0,report(Dataset.TICKETS).details().total());var events=report(Dataset.TICKET_EVENTS);assertEquals(2,events.details().total());assertTrue(events.details().rows().stream().anyMatch(r->r.contains("REOPEN_REQUESTED")));assertFalse(events.details().rows().stream().anyMatch(r->r.contains("REOPENED")));assertEquals(TicketStatus.RESOLVED,ticketRows.findById(id).orElseThrow().getStatus());assertTrue(events.metrics().stream().anyMatch(m->m.label().contains("giải quyết gần nhất")&&m.value().equals("864000.00")));assertFalse(events.toString().contains("PRIVATE"));}
    @Test void actualManagerReopenKeepsHistoricalResolutionButClearsCurrentDurationSample(){Long id=resolvedOldTicket();as(f.manager,"ROLE_MANAGER");tickets.reopen(id,new TicketCommands.Decision(ticketRows.findById(id).orElseThrow().getVersion(),"INTERNAL REOPEN REASON"));var view=report(Dataset.TICKET_EVENTS);assertEquals(2,view.details().total());assertTrue(view.details().rows().stream().anyMatch(r->r.contains("REOPENED")));assertTrue(view.metrics().stream().anyMatch(m->m.label().contains("giải quyết gần nhất")&&m.value().equals("N/A")));assertEquals(1,report(Dataset.OPEN_TICKETS).details().total());}
    @Test void unifiedAuditReadsAllExistingSourcesWithoutCopyingOrDuplicatingRows(){db(()->{var s=f.shipment(f.source,f.destination,ShipmentStatus.IN_TRANSIT,NOW);f.event(s,"PRIVATE SHIPMENT TEXT",ShipmentStatus.AT_ORIGIN_BRANCH,ShipmentStatus.IN_TRANSIT,NOW);var t=trip(f.source,f.hub,TransportLeg.COLLECTION,TripStatus.DEPARTED);var e=new TransportTripEvent();e.setTrip(t);e.setType(TripEventType.DEPARTED);e.setFromStatus(TripStatus.SEALED);e.setToStatus(TripStatus.DEPARTED);e.setActor(f.manager);e.setBranch(f.source);e.setNotes("INTERNAL TRANSPORT NOTES");e.setOccurredAt(NOW);em.persist(e);return s;});as(f.manager,"ROLE_MANAGER");tickets.create(command(db(()->em.createQuery("select s from Shipment s",Shipment.class).getSingleResult())));as(f.admin,"ROLE_ADMIN");adminUsers.lock(f.other.getId());var view=audit.read(new AuditViews.Request(Period.TODAY,null,null,null,null,null,null,null,null),0,50);assertEquals(4,view.total());assertEquals(Set.of("ADMIN","SHIPMENT","TRANSPORT","TICKET"),view.rows().stream().map(AuditViews.Row::source).collect(java.util.stream.Collectors.toSet()));assertEquals(4,view.rows().stream().map(r->r.source()+":"+r.id()).distinct().count());assertFalse(view.toString().contains("INTERNAL TRANSPORT"));assertFalse(view.toString().contains("PRIVATE SHIPMENT"));assertEquals(0,notices.count());}
    @Test void ticketAuditFilterSeparatesCustomerActorFromManagerAndHidesMessages(){Long id=resolvedOldTicket();as(f.owner,"ROLE_USER");tickets.requestCustomerReopen(id,new CustomerTicketCommands.Message(ticketRows.findById(id).orElseThrow().getVersion(),"INTERNAL MUST NOT LEAK",UUID.randomUUID().toString().replace("-","")));as(f.admin,"ROLE_ADMIN");var view=audit.read(new AuditViews.Request(Period.TODAY,null,null,AuditViews.Source.TICKET,f.owner.getId(),"REOPEN_REQUESTED","SUPPORT_TICKET",id.toString(),f.source.getId()),0,20);assertEquals(1,view.total());assertEquals(f.owner.getId(),view.rows().getFirst().actorId());assertFalse(view.toString().contains("MUST NOT LEAK"));}
    @Test void mixedServiceTripCountsOnlyMatchingParcelsWhenServiceFilterIsSet(){db(()->{var t=trip(f.source,f.hub,TransportLeg.COLLECTION,TripStatus.DEPARTED);t.setExpectedCount(2);item(t,f.shipment(f.source,f.destination,ShipmentStatus.IN_TRANSIT,NOW),false);var service=new ShippingService();service.setCode("OTHER_SERVICE");service.setName("Dịch vụ khác");service.setEstimatedDeliveryHours(24);em.persist(service);var other=f.shipment(f.source,f.destination,ShipmentStatus.IN_TRANSIT,NOW);other.setService(service);item(t,other,false);return null;});as(f.admin,"ROLE_ADMIN");var view=reports.read(new Request(Dataset.TRIPS,Period.TODAY,null,null,null,f.catalog.getId(),null,Trend.DAY),0,50);assertEquals(1,view.details().total());assertTrue(view.metrics().stream().anyMatch(m->m.label().equals("Lượt vận chuyển kiện/chặng")&&m.value().equals("1")));assertTrue(view.metrics().stream().anyMatch(m->m.label().equals("Vận đơn duy nhất qua các chặng")&&m.value().equals("1")));}
    @Test void unexpectedDiscrepancyIsNotAssignedToAnUnverifiedServiceByTripContents(){db(()->{var t=trip(f.source,f.hub,TransportLeg.COLLECTION,TripStatus.RECONCILING);item(t,f.shipment(f.source,f.destination,ShipmentStatus.IN_TRANSIT,NOW),false);var d=new TripDiscrepancy();d.setTrip(t);d.setKind(TripDiscrepancyKind.UNEXPECTED);d.setReference("UNEXPECTED");d.setNotes("PRIVATE");d.setActor(staff(f.hub).getUser());d.setEmployee(staff(f.hub));d.setRecordedAt(NOW);em.persist(d);return null;});assertEquals(1,report(Dataset.DISCREPANCIES).details().total());as(f.admin,"ROLE_ADMIN");var view=reports.read(new Request(Dataset.DISCREPANCIES,Period.TODAY,null,null,null,f.catalog.getId(),null,Trend.DAY),0,20);assertEquals(0,view.details().total());}
}
